em.Text.Json.JsonSerializer.Deserialize<OnlineArcadeRunStoreSnapshot>(File.ReadAllText(m.StorePath))!.Runs.Single();Require(restored.Players[0].RoundPowerups.Single().RemainingSeconds==11,"effect remaining amount not serialized");var resumed=OnlineArcadeRunActorSystem.PrepareBattle(restored,false);Require(resumed.WaveIndex==1&&resumed.Players[1].CurrentHealth==37,"restart resumed wrong round");Require(resumed.Crates[crateId].Health==partialHealth,"surviving crate restored full health");Require(resumed.Players[1].InvulnerabilitySeconds==4&&resumed.Players[1].DashSeconds==.7f&&resumed.Players[1].FireCooldownSeconds==.3f,"logical protection or cooldown lost at round node");}finally{Directory.Delete(folder,true);}}),
