 ("Papaback actual chase charge and ray use original boss configuration",()=>{var r=Record(10,20);var b=OnlineArcadeRunActorSystem.PrepareBattle(r,false);Call("PrepareWave",b,config.Tables.TbArcadeArena.Get(20),3);Call("PrepareRoundBoss",b);Call("TrySpawnEnemy",b,TimeInfo.Instance.ServerNow());var a=new OnlineArcadeRunActor{Record=r,Battle=b};var e=b.Enemies.Values.Single();foreach(var p in b.Players.Values){p.PositionX=0;p.PositionZ=10;}e.PositionX=e.PositionZ=0;e.BossSkillCooldownSeconds=e.BossRayCooldownSeconds=100;Call("TickEnemies",a,b,.1f);Require(e.PositionZ>0,"Papaback legacy chase absent between skills");e.PositionX=e.PositionZ=0;e.BossSkillCooldownSeconds=0;e.BossRayCooldownSeconds=100;Call("TickEnemies",a,b,.01f);Require(e.BossId=="arcade.boss.final"&&e.BossPhase==OnlineArcadeBossPhase.Telegraph&&e.BossPhaseSeconds>.8f,"Papaback did not enter configured charge telegraph");Call("TickEnemies",a,b,1f);Require(e.BossPhase==OnlineArcadeBossPhase.Charging,"Papaback never charged");b.Players[1].PositionZ=.1f;int hp=b.Players[1].CurrentHealth;Call("TickEnemies",a,b,.1f);Require(e.PositionZ>0&&b.Players[1].CurrentHealth<hp,"configured charge did not sweep hit");e.BossPhase=OnlineArcadeBossPhase.None;e.BossRayCooldownSeconds=0;e.BossSkillCooldownSeconds=100;Call("TickEnemies",a,b,.01f);Require(e.BossPhase==OnlineArcadeBossPhase.RayTelegraph,"Papaback ray telegraph absent");Call("TickEnemies",a,b,1f);Require(b.Projectiles.Count==1&&Math.Abs(Math.Sqrt(b.Projectiles.Values.Single().VelocityX*b.Projectiles.Values.Single().VelocityX+b.Projectiles.Values.Single().VelocityZ*b.Projectiles.Values.Single().VelocityZ)-10)<.01,"Papaback configured ray not fired");}),
