 ("Player shot crossing ground barrel detonates once and applies maximum-health explosion",()=>{var a=GroundActor();var b=a.Battle;var point=b.RoundLayout.Barrels[0];var target=new OnlineArcadeEnemyRuntime{RuntimeId=101,PositionX=point.X+1,PositionZ=point.Y,MaxHealth=200,CurrentHealth=100};b.Enemies[101]=target;b.EnemyIterationIds.Add(101);GroundShot(a,point.X-2,point.Y,point.X+2,point.Y);Call("TickProjectiles",a,b,1f);Require(GroundCount(b)==1&&b.Projectiles.Count==0,"crossed barrel did not consume exactly one player projectile");Require(target.CurrentHealth==76&&b.Players[1].CurrentHealth==88,"ground explosion did not apply per-target maximum-health ratio");Call("TickProjectiles",a,b,1f);Require(target.CurrentHealth==76&&GroundCount(b)==1,"repeat tick duplicated explosion");Require(b.DeathZones.Any(z=>z.Kind==3),"ground barrel missing shared explosion danger visual");}),
 ("Nearest ground barrel respects walls enemies crates and player-weapon origin",()=>{var a=GroundActor();var b=a.Battle;var first=b.RoundLayout.Barrels[0];var last=b.RoundLayout.Barrels[1];float dx=last.X-first.X,dy=last.Y-first.Y,len=MathF.Sqrt(dx*dx+dy*dy);GroundShot(a,first.X-dx/len*2,first.Y-dy/len*2,last.X+dx/len*2,last.Y+dy/len*2);Call("TickProjectiles",a,b,1f);var left=((OnlineArcadeBattleInfo)Call("BuildBattleSnapshot",b)).ContentAreas.Where(v=>v.Kind==11).ToArray();Require(left.Length==1&&left[0].Id==-10001,"shot did not select nearest barrel");foreach(int blocker in new[]{0,1,2,3,4,5}){a=GroundActor();b=a.Battle;first=b.RoundLayout.Barrels[0];OnlineArcadeProjectileRuntime shot;if(blocker==0){var obstacle=b.RoundLayout.Obstacles[0];float sx=obstacle.X*2-first.X,sy=obstacle.Y*2-first.Y;shot=GroundShot(a,sx,sy,first.X+(first.X-obstacle.X)*.3f,first.Y+(first.Y-obstacle.Y)*.3f);}else{shot=GroundShot(a,first.X-2,first.Y,first.X+2,first.Y);if(blocker==1)b.Enemies[9]=new(){RuntimeId=9,PositionX=first.X-1,PositionZ=first.Y,CurrentHealth=100,MaxHealth=100};if(blocker==2)b.Crates[9]=new FirepowerLoop.Arcade.ArcadeCrateState(new FirepowerLoop.Arcade.ArcadeBabylonParameters.Crate(9,first.X-1,first.Y,.2f,30));if(blocker==3){shot.OwnerPlayerId=0;}if(blocker==4)shot.FromPlayerWeapon=false;if(blocker==5)shot.RemainingSeconds=0;}Call("TickProjectiles",a,b,1f);Require(GroundCount(b)==2,"ground barrel fired through blocker or hostile origin "+blocker);}}),
 ("Ground barrel destruction survives same-map projection and round-node restore only",()=>{var a=GroundActor();var b=a.Battle;var point=b.RoundLayout.Barrels[0];var original=OnlineArcadeRunManagerSystem.Clone(a.Record);GroundShot(a,point.X-2,point.Y,point.X+2,point.Y);Call("TickProjectiles",a,b,1f);Call("PrepareWave",b,config.Tables.TbArcadeArena.Get(3),0);Require(GroundCount(b)==1,"same map preparation respawned destroyed barrel");var checkpoint=OnlineArcadeRunManagerSystem.Clone(a.Record);ManagerCall("CaptureRoundCheckpoint",checkpoint,b);var restored=OnlineArcadeRunActorSystem.PrepareBattle(OnlineArcadeRunManagerSystem.Clone(checkpoint),false);Require(GroundCount(restored)==1,"round node lost destroyed set");Require(GroundCount(OnlineArcadeRunActorSystem.PrepareBattle(original,false))==2,"round rollback did not restore original barrels with player resources");var property=typeof(OnlineArcadeRunRecord).GetProperty("DestroyedBarrelIds")!;var bad=OnlineArcadeRunManagerSystem.Clone(checkpoint);((System.Collections.IList)property.GetValue(bad)!).Add(99);bool rejected=false;try{OnlineArcadeRunActorSystem.PrepareBattle(bad,false);}catch(RpcException){rejected=true;}Require(rejected,"unknown ground barrel id restored");Call("PrepareWave",b,config.Tables.TbArcadeArena.Get(3),1);Require(GroundCount(b)==2,"new layout inherited previous map destroyed index");}),
 ("Explosive weapon hitting ground barrel preserves its own explosion damage and radius",()=>{var a=GroundActor();var b=a.Battle;var point=b.RoundLayout.Barrels[0];var near=new OnlineArcadeEnemyRuntime{RuntimeId=101,PositionX=point.X+1,PositionZ=point.Y,CurrentHealth=100,MaxHealth=200};var far=new OnlineArcadeEnemyRuntime{RuntimeId=102,PositionX=point.X+4,PositionZ=point.Y,CurrentHealth=100,MaxHealth=100};b.Enemies[101]=near;b.Enemies[102]=far;b.EnemyIterationIds.AddRange(new long[]{101,102});var shot=GroundShot(a,point.X-2,point.Y,point.X+2,point.Y);shot.Behavior=ArcadeWeaponBehavior.Explosive;shot.ExplosionRadius=6;shot.Damage=7;Call("TickProjectiles",a,b,1f);Require(GroundCount(b)==1&&b.Projectiles.Count==0,"explosive shot did not consume barrel hit once");Require(near.CurrentHealth==69,"barrel hit lost weapon's own additional explosion damage");Require(far.CurrentHealth==93,"barrel hit truncated original weapon explosion radius");Require(near.LastDamagePlayerId==1&&far.LastDamagePlayerId==1,"weapon explosion lost player attribution");}),
 ("Cross-frame player projectiles resolve nearer enemy and crate impact before ground barrel",()=>{
     var a=GroundActor();var b=a.Battle;var point=b.RoundLayout.Barrels[0];
     var enemy=new OnlineArcadeEnemyRuntime{RuntimeId=101,PositionX=point.X-4,PositionZ=point.Y,CurrentHealth=100,MaxHealth=100};
     b.Enemies[101]=enemy;b.EnemyIterationIds.Add(101);
     var shot=GroundShot(a,point.X-6,point.Y,point.X,point.Y);shot.Damage=7;
     Call("TickProjectiles",a,b,1f);int firstHealth=enemy.CurrentHealth;
     Call("TickProjectiles",a,b,1f);
     Require(firstHealth==93&&b.Projectiles.Count==0,"first crossing tick skipped the nearer enemy's actual damage");
     Require(GroundCount(b)==2,"next tick fired barrel from behind an unresolved enemy");
     a=GroundActor();b=a.Battle;point=b.RoundLayout.Barrels[0];
     b.Crates[201]=new FirepowerLoop.Arcade.ArcadeCrateState(new FirepowerLoop.Arcade.ArcadeBabylonParameters.Crate(201,point.X-4,point.Y,.2f,30));
     b.Crates[202]=new FirepowerLoop.Arcade.ArcadeCrateState(new FirepowerLoop.Arcade.ArcadeBabylonParameters.Crate(202,point.X-4.7f,point.Y+.6f,.01f,30));
     shot=GroundShot(a,point.X-6,point.Y,point.X,point.Y);shot.Damage=7;shot.Behavior=ArcadeWeaponBehavior.Explosive;shot.ExplosionRadius=.8f;
     Call("TickProjectiles",a,b,1f);Call("TickProjectiles",a,b,1f);
     Require(b.Crates[201].Health==16&&b.Crates[202].Health==23,"near crate impact did not anchor the original weapon blast to first contact");
     Require(GroundCount(b)==2&&b.Projectiles.Count==0,"crate-blocked shot survived to detonate barrel later");
     a=GroundActor();b=a.Battle;point=b.RoundLayout.Barrels[0];
     enemy=new(){RuntimeId=101,PositionX=point.X-4,PositionZ=point.Y,CurrentHealth=100,MaxHealth=100};b.Enemies[101]=enemy;b.EnemyIterationIds.Add(101);
     shot=GroundShot(a,point.X-6,point.Y,point.X,point.Y);shot.Behavior=ArcadeWeaponBehavior.Piercing;shot.RemainingHits=2;shot.HitEnemyIds.Add(101);
     Call("TickProjectiles",a,b,1f);
     Require(GroundCount(b)==1&&b.Projectiles.Count==0,"already-hit piercing target blocked the later barrel contact");
 }),
 ("Fortieth round retains final encounter boundary",()=>{var r=Record(10,20);var b=OnlineArcadeRunActorSystem.PrepareBattle(r,false);var a=new OnlineArcadeRunActor{Record=r,Battle=b};Call("PrepareWave",b,config.Tables.TbArcadeArena.Get(20),3);b.SpawnQueueIndex=b.SpawnQueue.Count;Call("TryAdvanceWave",a,b,0f);Require(!b.ArenaCompletionReady&&b.WaveIndex==3,"fortieth round ended run");})
};
if(tests.Length>max)throw new InvalidOperationException("Test limit exceeded");int failures=0;
foreach(var(name,test)in tests)try{test();Console.WriteLine("PASS FullRouteOnline."+name);}catch(Exception ex){failures++;Console.WriteLine("FAIL FullRouteOnline."+name+": "+(ex.InnerException??ex).ToString());}
Console.WriteLine($"{tests.Length-failures}/{tests.Length} passed");Environment.ExitCode=failures==0?0:1;
